package com.hotelmanagement.hms.housekeeping.web; import com.hotelmanagement.hms.housekeeping.dto.*; import com.hotelmanagement.hms.housekeeping.model.*; import com.hotelmanagement.hms.housekeeping.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*; @RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/housekeeping/tasks") public class HousekeepingTaskController{private final HousekeepingTaskService s;public HousekeepingTaskController(HousekeepingTaskService s){this.s=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public UUID create(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid@RequestBody HousekeepingTaskRequest q){return s.create(hotel,branch,q);}@PostMapping("/{id}/{status}")@ResponseStatus(HttpStatus.NO_CONTENT)public void update(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id,@PathVariable HousekeepingTaskStatus status){s.update(hotel,branch,id,status);}}
